 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}
 static void Check(string n,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}
 static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(160)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static T Find<T>(DependencyObject o,Func<T,bool> test)where T:DependencyObject{var r=o as T;if(r!=null&&test(r))return r;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var v=Find<T>(VisualTreeHelper.GetChild(o,i),test);if(v!=null)return v;}return null;}
 static T Named<T>(DependencyObject o,string n)where T:DependencyObject{return Find<T>(o,x=>System.Windows.Automation.AutomationProperties.GetName(x)==n);}
 static void Click(Window w,string label){var b=Find<Button>(w,x=>Convert.ToString(x.Content)==label);if(b==null)throw new Exception("Missing button "+label);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static void Shot(Window w,string path){w.UpdateLayout();var r=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)r.ActualWidth,(int)r.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(r);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
